export class AgentOnboardingModalComponent implements OnChanges, OnDestroy {
  @Input() open = false;
  @Input() initialMode: 'sign-up' | 'sign-in' = 'sign-up';
  @Input() preview: AgentHomePortfolioPreview | null = null;
  @Input() selectedAgentNames: string[] = [];
  @Output() closed = new EventEmitter<void>();
  @ViewChild('googleButton') private googleButton?: ElementRef<HTMLElement>;

  readonly agentData = inject(AgentDataService); private readonly billing = inject(BillingService); private readonly scripts = inject(ScriptLoaderService); private readonly winRef = inject(WindowRefService); private readonly dataService = inject(DataService); private readonly storage = inject(LocalStorageService); private readonly loading = inject(LoadingService); private readonly auth = inject(AuthService); readonly googleSignIn = inject(GoogleSignInService); private readonly recaptcha = inject(ReCaptchaV3Service); private readonly toastr = inject(ToastrService); private readonly router = inject(Router);
  readonly stage = signal<'account' | 'portfolio' | 'trial'>('account'); readonly mode = signal<'sign-up' | 'sign-in'>('sign-up'); readonly portfolioMethod = signal<'registry' | 'upload'>('registry'); readonly trialBilling = signal<'annual' | 'monthly'>('annual'); readonly submitting = signal(false); readonly error = signal('');
  readonly registrySuggestions = signal<AgentHomeDirectoryEntry[]>([]); readonly registrySelections = signal<AgentHomeDirectoryEntry[]>([]); readonly registrySearching = signal(false); readonly registrySearchError = signal('');
  readonly trialPlans = signal<SubscriptionPlan[]>([]); readonly trialPlanLoading = signal(false); readonly trialCheckoutError = signal('');
  readonly trialPlan = computed(() => this.trialPlans().find(plan => plan.billingInterval === (this.trialBilling() === 'annual' ? 'ANNUAL' : 'MONTHLY')) ?? null);
  private readonly registrySearch$ = new Subject<string>(); private readonly destroyed$ = new Subject<void>();
  formData: AgentRegistration = this.emptyForm(); signInData = new Login(); passwordVisible = false; signInPasswordVisible = false;

  registryQuery = '';

  constructor() {
    this.registrySearch$.pipe(debounceTime(250), distinctUntilChanged(), switchMap(query => {
      if (query.trim().length < 2) return of<AgentHomeDirectoryEntry[]>([]);
      this.registrySearching.set(true); this.registrySearchError.set('');
      return this.agentData.searchPublicAgentPreview(query.trim());
    }), takeUntil(this.destroyed$)).subscribe({
      next: results => { this.registrySuggestions.set(results); this.registrySearching.set(false); },
      error: () => { this.registrySearchError.set('We could not search the register right now. Please try again.'); this.registrySuggestions.set([]); this.registrySearching.set(false); },
    });
  }

  ngOnChanges(changes: SimpleChanges): void { if (changes['open']?.currentValue && !changes['open'].previousValue) { this.reset(this.initialMode); setTimeout(() => this.renderGoogleButton()); } }
  ngOnDestroy(): void { this.destroyed$.next(); this.destroyed$.complete(); }
  requestClose(): void {
    if (this.submitting()) return;
    const accountCreated = this.stage() !== 'account';
    this.reset();
    if (accountCreated) return this.go(['/agent-portal/dashboard']);
    this.closed.emit();
  }
  showSignIn(): void { this.mode.set('sign-in'); this.error.set(''); setTimeout(() => this.renderGoogleButton()); }
  showSignUp(): void { this.mode.set('sign-up'); this.error.set(''); setTimeout(() => this.renderGoogleButton()); }
  submitRegistration(): void { this.error.set(''); if (!this.formData.firstName.trim() || !this.formData.email || !this.formData.password) return this.error.set('Complete your name, email, and password to continue.'); if (this.formData.password.length < 6) return this.error.set('Your password must be at least 6 characters.'); this.formData.firstName = this.formData.firstName.trim(); this.submitting.set(true); this.loading.show(); this.recaptcha.execute('agent_register').subscribe({next: token => { this.formData.captchaResponse = token; this.agentData.registerAgent(this.formData).pipe(finalize(() => this.loading.hide())).subscribe({next: () => this.loginAndStartPortfolioSetup(), error: err => this.fail(err?.error?.detail || 'Registration failed. Please try again.')}); }, error: () => this.fail('CAPTCHA verification failed. Please try again.')}); }
  submitSignIn(): void { this.error.set(''); this.signInData.username = this.signInData.username?.trim(); if (!this.signInData.username || !this.signInData.password) return this.error.set('Enter your email and password to sign in.'); this.submitting.set(true); this.loading.show(); this.dataService.login(this.signInData.forRequest()).subscribe({next: response => this.completeSignIn(response), error: err => this.fail(err?.error?.detail?.includes('Bad Credentials') ? 'Incorrect email or password.' : err?.error?.detail || 'Could not sign you in. Please try again.')}); }
  /** Advances only from the footer. Selecting an import method must never skip Step 2. */
  continuePortfolioSetup(): void {
    // A spreadsheet or a deferred portfolio has no verified mark count yet, so it always moves to
    // plan selection. The eventual import can determine eligibility from the actual saved marks.
    if (this.portfolioMethod() === 'upload') return this.showTrial();
    const claims = this.registryClaimNames();
    if (!claims.length) return this.showTrial();

    this.submitting.set(true);
    forkJoin(claims.map(agentName => this.agentData.claimTrademarks({agentName, claimAllUnderName: true}))).subscribe({
      next: () => this.advanceAfterRegistrySync(),
      error: () => {
        this.submitting.set(false);
        this.toastr.error('Your account is ready, but we could not add those trademarks. You can retry from your portfolio.');
        this.go(['/agent-portal/dashboard']);
      },
    });
  }
  onRegistryQueryChange(query: string): void { this.registryQuery = query; if (query.trim().length < 2) { this.registrySearch$.next(''); this.registrySuggestions.set([]); this.registrySearchError.set(''); this.registrySearching.set(false); return; } this.registrySearch$.next(query); }
  searchRegistry(): void { const query = this.registryQuery.trim(); if (query.length < 2) { this.registrySearchError.set('Type at least two characters to search the register.'); return; } this.registrySearch$.next(query); }
  isRegistryAgentSelected(entry: AgentHomeDirectoryEntry): boolean { return this.registrySelections().some(selected => selected.agentName === entry.agentName); }
  selectPortfolioMethod(method: 'registry' | 'upload'): void { this.portfolioMethod.set(method); }
  toggleRegistryAgent(entry: AgentHomeDirectoryEntry): void { const selections = this.registrySelections(); this.registrySelections.set(this.isRegistryAgentSelected(entry) ? selections.filter(selected => selected.agentName !== entry.agentName) : [...selections, entry]); this.portfolioMethod.set('registry'); }
  confirmRegistrySelection(): void { this.registrySuggestions.set([]); this.registrySearchError.set(''); }
  /** A portfolio that has not been connected yet contains zero marks, so it retains free full access. */
  skipPortfolioSetup(): void { this.go(['/agent-portal/dashboard']); }
  startProTrial(): void {
    const plan = this.trialPlan();
    if (!plan) return this.trialCheckoutError.set('The selected plan is not available yet. Please wait a moment and try again.');
    this.submitting.set(true); this.trialCheckoutError.set('');
    void this.scripts.load('https://checkout.razorpay.com/v1/checkout.js').then(() => {
      this.billing.startSubscription(plan.code).subscribe({ next: session => this.openRazorpay(session), error: err => this.failTrialCheckout(this.messageOf(err, 'Could not start secure checkout. Please try again.')) });
    }).catch(() => this.failTrialCheckout('The payment window could not load. Check that checkout.razorpay.com is not blocked, then try again.'));
  }
  trialAnnualSavingPercent(): number { const monthly = this.trialPlans().find(plan => plan.billingInterval === 'MONTHLY'); const annual = this.trialPlans().find(plan => plan.billingInterval === 'ANNUAL'); if (!monthly || !annual || monthly.amountPaise <= 0) return 0; return Math.round((1 - annual.amountPaise / (monthly.amountPaise * 12)) * 100); }
  trialPlanPriceLabel(): string { const plan = this.trialPlan(); if (!plan) return this.trialPlanLoading() ? 'Loading…' : 'Plan unavailable'; return `${this.rupees(plan.amountPaise)}${plan.billingInterval === 'ANNUAL' ? '/year' : '/month'}`; }
  trialPlanBillingDetail(): string { const plan = this.trialPlan(); if (!plan) return 'Your exact billing amount will appear here.'; return plan.billingInterval === 'ANNUAL' ? `Billed annually after 14 days at ${this.rupees(plan.amountPaise)} (${this.rupees(plan.monthlyEquivalentPaise)}/mo)` : `14 days free, then ${this.rupees(plan.amountPaise)}/month billed monthly`; }
  private loginAndStartPortfolioSetup(): void { const login = new Login(); login.username = this.formData.email; login.password = this.formData.password; this.dataService.login(login.forRequest()).subscribe({next: response => { const token = response.body?.id_token; if (!token) return this.fail('Your account was created, but sign-in could not be completed. Please sign in to continue.'); this.storeToken(token); this.submitting.set(false); this.stage.set('portfolio'); }, error: () => this.fail('Your account was created, but sign-in failed. Please sign in to continue.')}); }
  private completeSignIn(response: any): void { const token = response.body?.id_token; if (!token) return this.fail('Could not sign you in. Please try again.'); this.storeToken(token); this.loading.hide(); this.submitting.set(false); if (this.auth.hasRole(['ROLE_AGENT'])) this.go(['/agent-portal/dashboard']); else this.error.set('This is the agent portal. Your account signs in on the main site.'); }
  private renderGoogleButton(): void { if (!this.googleButton?.nativeElement || !this.googleSignIn.configured) return; void this.googleSignIn.renderButton(this.googleButton.nativeElement, credential => this.mode() === 'sign-in' ? this.signInWithGoogle(credential) : this.registerWithGoogle(credential)).catch(() => this.error.set('Google sign-in could not be loaded. Please use email registration.')); }
  private registerWithGoogle(credential: string): void { this.submitting.set(true); this.loading.show(); this.dataService.loginAgentWithGoogle(credential).subscribe({next: response => { this.loading.hide(); const token = response.body?.id_token; if (!token) return this.fail('Google sign-in could not be completed.'); this.storeToken(token); if (!this.auth.hasRole(['ROLE_AGENT'])) return this.fail('This Google account is not linked to an agent portal account.'); this.submitting.set(false); this.stage.set('portfolio'); }, error: err => this.fail(err?.error?.detail || 'Google sign-in could not be completed.')}); }
  private signInWithGoogle(credential: string): void { this.submitting.set(true); this.loading.show(); this.dataService.loginAgentWithGoogle(credential).subscribe({next: response => this.completeSignIn(response), error: err => this.fail(err?.error?.detail || 'Google sign-in could not be completed.')}); }
  private storeToken(token: string): void { this.storage.storeAuthenticationToken(token); const {id, authorities} = this.auth.decodeToken(token); this.storage.setObject('user', {id, authorities}); }
  private go(commands: string[], extras?: object): void { this.closed.emit(); void this.router.navigate(commands, extras); }
  private fail(message: string): void { this.loading.hide(); this.submitting.set(false); this.error.set(message); }
  /** The API owns eligibility. It counts the claims that just committed before choosing a route. */
  private advanceAfterRegistrySync(): void {
    this.billing.loadState().pipe(finalize(() => this.submitting.set(false))).subscribe({
      next: state => state.freeUnlimitedAccess ? this.go(['/agent-portal/dashboard']) : this.showTrial(),
      // When the state check is unavailable, retain the paid-plan route rather than granting a
      // client-side bypass. The user can still complete onboarding normally.
      error: () => this.showTrial(),
    });
  }
  showTrial(): void { this.stage.set('trial'); this.trialCheckoutError.set(''); this.loadTrialPlans(); if (typeof document !== 'undefined') void this.scripts.load('https://checkout.razorpay.com/v1/checkout.js').catch(() => undefined); }
  private loadTrialPlans(): void { if (this.trialPlans().length || this.trialPlanLoading()) return; this.trialPlanLoading.set(true); this.billing.getPlans().pipe(finalize(() => this.trialPlanLoading.set(false))).subscribe({ next: plans => { this.trialPlans.set(plans); if (!plans.some(plan => plan.billingInterval === 'MONTHLY') || !plans.some(plan => plan.billingInterval === 'ANNUAL')) this.trialCheckoutError.set('Plans are not available right now. Please try again later.'); }, error: () => this.trialCheckoutError.set('Could not load the current plan prices. Please try again.') }); }
  private openRazorpay(session: { razorpaySubscriptionId: string; razorpayKeyId: string; planName: string; prefill: { name: string | null; email: string | null; contact: string | null } | null }): void { const Razorpay = this.winRef.nativeWindow?.Razorpay; if (!Razorpay) return this.failTrialCheckout('The payment window could not load. Please try again.'); const checkout = new Razorpay({ key: session.razorpayKeyId, subscription_id: session.razorpaySubscriptionId, name: 'Trademarx', description: session.planName, image: '/assets/images/trademarx.svg', prefill: { name: session.prefill?.name ?? '', email: session.prefill?.email ?? '', contact: session.prefill?.contact ?? '' }, theme: { color: '#3525cd' }, handler: (result: { razorpay_payment_id: string; razorpay_subscription_id: string; razorpay_signature: string }) => this.confirmTrialCheckout(result), modal: { ondismiss: () => { this.submitting.set(false); } } }); checkout.on('payment.failed', (response: any) => this.failTrialCheckout(response?.error?.description || "That payment didn't go through. You haven't been charged.")); checkout.open(); }
  private confirmTrialCheckout(result: { razorpay_payment_id: string; razorpay_subscription_id: string; razorpay_signature: string }): void { this.billing.verify(result).subscribe({ next: () => { this.toastr.success('Autopay is authorised. Your 14-day Pro trial is ready.'); this.go(['/agent-portal/dashboard']); }, error: () => this.failTrialCheckout("Razorpay received your approval, but we're still confirming it. Check the dashboard in a moment; you do not need to pay again.") }); }
  private failTrialCheckout(message: string): void { this.submitting.set(false); this.trialCheckoutError.set(message); }
  private rupees(paise: number): string { const rupees = paise / 100; return '₹' + rupees.toLocaleString('en-IN', { minimumFractionDigits: rupees % 1 === 0 ? 0 : 2, maximumFractionDigits: 2 }); }
  private messageOf(err: any, fallback: string): string { const detail = err?.error?.detail; return typeof detail === 'string' && detail.trim() ? detail : fallback; }
  registryClaimCount(): number { return this.registryClaimNames().length; }
  registrySelectedTrademarkCount(): number { const selected = this.registrySelections(); return selected.length ? selected.reduce((total, entry) => total + entry.markCount, 0) : this.preview?.totalMarks ?? 0; }
  /** Step 2 can promise free access only after a verified registry selection below 100 marks. */
  hasFreePortfolioAccess(): boolean { return this.portfolioMethod() === 'registry' && this.registryClaimNames().length > 0 && this.registrySelectedTrademarkCount() < 100; }
  canSkipPlanSelection(): boolean { return this.hasFreePortfolioAccess(); }
  private registryClaimNames(): string[] { return [...new Set([...this.selectedAgentNames, ...this.registrySelections().map(entry => entry.agentName), ...(this.preview ? [this.preview.agentName] : [])])]; }
  private reset(mode: 'sign-up' | 'sign-in' = 'sign-up'): void { this.stage.set('account'); this.mode.set(mode); this.portfolioMethod.set('registry'); this.trialBilling.set('annual'); this.submitting.set(false); this.error.set(''); this.trialPlans.set([]); this.trialPlanLoading.set(false); this.trialCheckoutError.set(''); this.registryQuery = ''; this.registrySuggestions.set([]); this.registrySelections.set([]); this.registrySearching.set(false); this.registrySearchError.set(''); this.formData = this.emptyForm(); this.signInData = new Login(); this.passwordVisible = false; this.signInPasswordVisible = false; }
  private emptyForm(): AgentRegistration { return {firstName: '', lastName: '', email: '', password: '', captchaResponse: ''}; }
}
